# -*- coding: utf-8 -*-

SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">1. ÜNİTE ÖZETİ: İMAN VE İSLAM ESASLARININ BÜTÜNLÜĞÜ</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">İmanın Altı Şartı (İnanç)</text>\n  <text x="125" y="98" text-anchor="middle" font-size="11" fill="#334155">1. Allah\'ın varlığına ve birliğine</text>\n  <text x="125" y="118" text-anchor="middle" font-size="11" fill="#334155">2. Meleklerine iman</text>\n  <text x="125" y="138" text-anchor="middle" font-size="11" fill="#334155">3. İlahi kitaplarına iman</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#334155">4. Peygamberlerine iman</text>\n  <text x="125" y="178" text-anchor="middle" font-size="11" fill="#334155">5. Ahiret gününe iman</text>\n  <text x="125" y="198" text-anchor="middle" font-size="11" fill="#334155">6. Kader ve kazaya iman</text>\n  <text x="125" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">Özü: Kelime-i Tevhid ve Şehadet</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">İslam\'ın Beş Şartı (Uygulama)</text>\n  <text x="350" y="102" text-anchor="middle" font-size="11" fill="#334155">1. Kelime-i Şehadet getirmek</text>\n  <text x="350" y="126" text-anchor="middle" font-size="11" fill="#334155">2. Günde beş vakit namaz kılmak</text>\n  <text x="350" y="150" text-anchor="middle" font-size="11" fill="#334155">3. Ramazan ayında oruç tutmak</text>\n  <text x="350" y="174" text-anchor="middle" font-size="11" fill="#334155">4. Zekât vermek (Zenginler için)</text>\n  <text x="350" y="198" text-anchor="middle" font-size="11" fill="#334155">5. Hacca gitmek (Gücü yetenler)</text>\n  <text x="350" y="222" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">İman ağacın kökü, ibadet meyvesidir</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Esmâ-i Hüsnâ (Güzel İsimler)</text>\n  <text x="575" y="98" text-anchor="middle" font-size="11" fill="#334155">• el-Hâlık (Yaratan) / er-Rezzâk</text>\n  <text x="575" y="120" text-anchor="middle" font-size="11" fill="#334155">• er-Rahmân / er-Rahîm</text>\n  <text x="575" y="142" text-anchor="middle" font-size="11" fill="#334155">• el-Alîm / es-Semî / el-Basîr</text>\n  <text x="575" y="164" text-anchor="middle" font-size="11" fill="#334155">• el-Kâdir (Her şeye gücü yeten)</text>\n  <text x="575" y="186" text-anchor="middle" font-size="11" fill="#334155">• el-Hâdî / es-Selâm / el-Vekîl</text>\n  <text x="575" y="216" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">Çalışıp Allah\'a güvenmek: Tevekkül</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">2. ÜNİTEYE GİRİŞ: İSLAM\'DA İBADET KAVRAMI VE KABUL ŞARTLARI</text>\n  <rect x="25" y="48" width="315" height="190" rx="8" fill="#faf5ff" stroke="#a855f7" stroke-width="1.5"/>\n  <text x="182" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#7e22ce">İbadetin Tanımı ve Amacı</text>\n  <text x="182" y="100" text-anchor="middle" font-size="11" fill="#334155">Allah\'a (c.c.) saygı, bağlılık ve itaat</text>\n  <text x="182" y="118" text-anchor="middle" font-size="11" fill="#334155">göstermek; O\'nun rızasını kazanmak için</text>\n  <text x="182" y="136" text-anchor="middle" font-size="11" fill="#334155">emirlerini yerine getirip yasaklarından</text>\n  <text x="182" y="154" text-anchor="middle" font-size="11" fill="#334155">kaçınmaya "İBADET" denir.</text>\n  <text x="182" y="184" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">"Ben cinleri ve insanları ancak bana kulluk</text>\n  <text x="182" y="202" text-anchor="middle" font-size="11" font-weight="bold" fill="#6b21a8">(ibadet) etsinler diye yarattım." (Zâriyât, 56)</text>\n  <text x="182" y="224" text-anchor="middle" font-size="11" fill="#475569">Mükellef: Akıllı ve ergenlik çağına ulaşmış kişi</text>\n\n  <rect x="360" y="48" width="315" height="190" rx="8" fill="#fff1f2" stroke="#f43f5e" stroke-width="1.5"/>\n  <text x="517" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#be123c">İbadetlerin Kabul Olma İlkeleri</text>\n  <text x="380" y="104" font-size="12" font-weight="bold" fill="#9f1239">1. Sağlam Bir İman:</text>\n  <text x="390" y="122" font-size="11" fill="#334155">İbadetlerin geçerli olması için öncelikle</text>\n  <text x="390" y="138" font-size="11" fill="#334155">iman esaslarına gönülden inanmak şarttır.</text>\n  <text x="380" y="164" font-size="12" font-weight="bold" fill="#9f1239">2. İhlas (Samimiyet):</text>\n  <text x="390" y="182" font-size="11" fill="#334155">Gösterişten (riya) uzak durup ibadeti</text>\n  <text x="390" y="198" font-size="11" fill="#334155">Allah\'ın rızasını kazanmak için yapmaktır.</text>\n  <text x="380" y="222" font-size="12" font-weight="bold" fill="#9f1239">3. Sünnete Uygunluk: Peygamberimiz gibi yapmak.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="28" text-anchor="middle" font-size="15" font-weight="bold" fill="#1e293b">YAPILIŞ ŞEKLİNE GÖRE İBADET ÇEŞİTLERİ VE SALİH AMEL</text>\n  <rect x="20" y="48" width="210" height="190" rx="8" fill="#eff6ff" stroke="#3b82f6" stroke-width="1.5"/>\n  <text x="125" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#1d4ed8">Bedenle Yapılanlar</text>\n  <text x="125" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Namaz Kılmak</text>\n  <text x="125" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#1e3a8a">• Oruç Tutmak</text>\n  <text x="125" y="158" text-anchor="middle" font-size="11" fill="#334155">Zenginlik şartı aranmaz;</text>\n  <text x="125" y="176" text-anchor="middle" font-size="11" fill="#334155">fiziksel güç ve sağlıkla</text>\n  <text x="125" y="194" text-anchor="middle" font-size="11" fill="#334155">bizzat yerine getirilir.</text>\n  <text x="125" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#2563eb">(Vekâlet verilmez)</text>\n\n  <rect x="245" y="48" width="210" height="190" rx="8" fill="#f0fdf4" stroke="#22c55e" stroke-width="1.5"/>\n  <text x="350" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#15803d">Malla Yapılanlar</text>\n  <text x="350" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Zekât Vermek</text>\n  <text x="350" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#14532d">• Sadaka ve Kurban</text>\n  <text x="350" y="158" text-anchor="middle" font-size="11" fill="#334155">Dinen zengin sayılan (nisap</text>\n  <text x="350" y="176" text-anchor="middle" font-size="11" fill="#334155">miktarı mala sahip) kişilerin</text>\n  <text x="350" y="194" text-anchor="middle" font-size="11" fill="#334155">malından yaptığı ibadetlerdir.</text>\n  <text x="350" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#166534">(Toplumsal yardımlaşma sağlar)</text>\n\n  <rect x="470" y="48" width="210" height="190" rx="8" fill="#fefce8" stroke="#eab308" stroke-width="1.5"/>\n  <text x="575" y="72" text-anchor="middle" font-size="13" font-weight="bold" fill="#a16207">Hem Beden Hem Malla</text>\n  <text x="575" y="102" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">• Hacca Gitmek</text>\n  <text x="575" y="128" text-anchor="middle" font-size="12" font-weight="bold" fill="#713f12">• Umre Yapmak</text>\n  <text x="575" y="158" text-anchor="middle" font-size="11" fill="#334155">Hem maddi yol masrafını</text>\n  <text x="575" y="176" text-anchor="middle" font-size="11" fill="#334155">karşılamayı hem de Kâbe</text>\n  <text x="575" y="194" text-anchor="middle" font-size="11" fill="#334155">ve kutsal mekânlarda</text>\n  <text x="575" y="220" text-anchor="middle" font-size="11" font-weight="bold" fill="#854d0e">bedenen bulunmayı gerektirir.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
